## Streaming Replication Setup (PostgreSQL configuration)

```ini
# postgresql.conf on primary
wal_level = replica
max_wal_senders = 3
wal_keep_size = 1GB

# pg_hba.conf on primary — allow replica to connect
# TYPE   DATABASE  USER         ADDRESS     METHOD
host     replication replicator  10.0.0.2/32 scram-sha-256
```

```bash
# Initialize replica from primary
pg_basebackup -h primary-host -U replicator -D /var/lib/postgresql/data --wal-method=stream
```

## Spring: Read/Write Routing DataSource

```java
@Configuration
public class DataSourceConfig {

    @Bean
    @Primary
    public DataSource routingDataSource(
        @Qualifier("primaryDataSource") DataSource primary,
        @Qualifier("replicaDataSource") DataSource replica
    ) {
        Map<Object, Object> sources = new HashMap<>();
        sources.put("primary", primary);
        sources.put("replica",  replica);

        AbstractRoutingDataSource routing = new AbstractRoutingDataSource() {
            @Override
            protected Object determineCurrentLookupKey() {
                // Route read-only transactions to replica
                return TransactionSynchronizationManager.isCurrentTransactionReadOnly()
                    ? "replica" : "primary";
            }
        };
        routing.setTargetDataSources(sources);
        routing.setDefaultTargetDataSource(primary);
        return routing;
    }
}

// Usage:
@Transactional(readOnly = true)  // → routes to replica
public List<Product> getAllProducts() { ... }

@Transactional                   // → routes to primary
public Product createProduct(ProductDTO dto) { ... }
```

## Lag Monitoring

```sql
-- On replica: check how far behind primary
SELECT NOW() - pg_last_xact_replay_timestamp() AS replication_lag;

-- On primary: check all replica lag
SELECT client_addr,
       write_lag, flush_lag, replay_lag
FROM pg_stat_replication;
```
